xml.Script:
        clRed          := 'C80000';
        clOrange       := 'FF800A';
        clBlue         := '0000C8';
        clGreen        := '009600';
        clYellow       := 'FFFF00';
        clWhite        := 'FFFFFF';
        clLightViolett := 'FF0080';
        clViolett      := '800080';
        clLightBlue    := '7A7AFF';
        clCyan         := '00DCB4';

        for i := 0 to 3 do
            Colors[i] := -1;
        Colors[4] := clOrange;
        Colors[5] := clRed;

        W := 0.5;
        D := W / 3;
        DCut := W * 2 * sqrt(2) / 3;

        WX := D;
        WY := D;
        WZ := W;
        DWX := W+D;

Macro.Script:
Colors[1] := c1;
Colors[2] := c1;
Colors[3] := c2;
